#include "native_ink.h"
#include "product_services.h"
#include <QSet>
#include <QStringList>
#include <algorithm>
#include <cmath>
#include <vector>
namespace nativeink {namespace {
QPointF point(QJsonValue value){auto a=value.toArray();product::require((a.size()==2||a.size()==3)&&a[0].isDouble()&&a[1].isDouble(),"ink-point-schema");QPointF p(a[0].toDouble(),a[1].toDouble());product::require(std::isfinite(p.x())&&std::isfinite(p.y())&&p.x()>=0&&p.x()<=1480&&p.y()>=0&&p.y()<=17000,"ink-point-bounds");if(a.size()==3)product::require(a[2].isDouble()&&a[2].toDouble()>=0&&a[2].toDouble()<=1,"ink-pressure");return p;}
double distance(QPointF p,QPointF a,QPointF b){auto d=b-a;double length=QPointF::dotProduct(d,d),t=length?std::clamp(QPointF::dotProduct(p-a,d)/length,0.0,1.0):0;return std::hypot((p-a-d*t).x(),(p-a-d*t).y());}
bool inside(QPointF p,const QJsonArray& ring){bool yes=false;for(int i=0,j=ring.size()-1;i<ring.size();j=i++){auto a=point(ring[i]),b=point(ring[j]);if(distance(p,a,b)<0.001)return true;if((a.y()>p.y())!=(b.y()>p.y())&&p.x()<(b.x()-a.x())*(p.y()-a.y())/(b.y()-a.y())+a.x())yes=!yes;}return yes;}
bool selectedKind(const QString& kind){return QStringList{"tom_handwriting","tom_illustration","chart","diagram"}.contains(kind);}
}
void checkCancelled(const std::atomic<bool>* stop){product::require(!stop||!stop->load(std::memory_order_acquire),"tom-ink-canceled");}
QRectF bounds(const QJsonArray& strokes){double x0=1480,y0=17000,x1=0,y1=0;bool any=false;for(auto value:strokes){auto s=value.toObject();QJsonArray paths{s["points"].toArray()};for(auto hole:s["holes"].toArray())paths.append(hole);for(auto path:paths)for(auto v:path.toArray()){auto p=point(v);x0=std::min(x0,p.x());y0=std::min(y0,p.y());x1=std::max(x1,p.x());y1=std::max(y1,p.y());any=true;}}return any?QRectF(x0,y0,std::max(.01,x1-x0),std::max(.01,y1-y0)):QRectF{};}
namespace {Group checkedLimits(QJsonArray strokes,QString kind,unsigned maxStrokes,unsigned maxPoints){product::require(selectedKind(kind)&&!strokes.isEmpty()&&strokes.size()<=int(maxStrokes),"tom-ink-group-capacity");Group g;g.kind=kind;g.strokes=std::move(strokes);for(auto value:g.strokes){product::require(value.isObject(),"tom-ink-stroke-schema");auto s=value.toObject();if(s.contains("component"))product::require(s["component"].isString()&&!s["component"].toString().isEmpty()&&s["component"].toString().size()<=256&&!s["component"].toString().contains(QChar(0)),"visual-component-id");product::validateStyle(s["style"].toObject());(void)product::fillOpacity(s);const auto points=s["points"].toArray();product::require(!points.isEmpty()&&points.size()<=MaxPathPoints,"tom-ink-path-capacity");if(s.contains("shape"))product::require(s["shape"]=="polygon"&&points.size()>=3,"tom-ink-shape");QPointF previous;for(int i=0;i<points.size();++i){auto p=point(points[i]);product::require(++g.points<=maxPoints,"tom-ink-point-capacity");if(i)g.travel+=std::hypot((p-previous).x(),(p-previous).y());previous=p;}}for(auto value:g.strokes){auto holes=value.toObject()["holes"].toArray();product::require(holes.size()<=128,"tom-ink-holes-capacity");for(auto hole:holes){auto ring=hole.toArray();product::require(value.toObject()["shape"]=="polygon"&&ring.size()>=3&&ring.size()<=MaxPathPoints,"tom-ink-hole-schema");for(auto v:ring){point(v);product::require(++g.points<=maxPoints,"tom-ink-point-capacity");}}}g.bounds=bounds(g.strokes);return g;}}
Group checked(QJsonArray strokes,QString kind){bool visual=kind=="tom_illustration";return checkedLimits(std::move(strokes),std::move(kind),visual?MaxVisualStrokes:MaxStrokes,visual?MaxVisualPoints:MaxPoints);}
QJsonArray transform(QJsonArray strokes,const QJsonArray& matrix,QString color){QPointF origin;product::require(product::transformPoint(matrix,{0,0},origin),"tom-ink-transform");if(!color.isEmpty())product::require(QStringList{"black","pink","green","orange","yellow","purple","blue","red"}.contains(color),"tom-ink-color");for(int i=0;i<strokes.size();++i){auto s=strokes[i].toObject();QJsonArray next;for(auto value:s["points"].toArray()){auto p=point(value),mapped=QPointF{};product::require(product::transformPoint(matrix,p,mapped),"tom-ink-transform");QJsonArray a{mapped.x(),mapped.y()};if(value.toArray().size()==3)a.append(value.toArray()[2]);point(a);next.append(a);}s["points"]=next;if(!color.isEmpty()){auto style=s["style"].toObject();style["color"]=color;style.remove("rgb");s["style"]=style;} /* choosing an ink replaces an exact color */QJsonArray holes;for(auto hole:s["holes"].toArray()){QJsonArray ring;for(auto value:hole.toArray()){QPointF mapped;product::require(product::transformPoint(matrix,point(value),mapped),"tom-ink-transform");QJsonArray p{mapped.x(),mapped.y()};point(p);ring.append(p);}holes.append(ring);}if(s.contains("holes"))s["holes"]=holes;strokes[i]=s;}checkedLimits(strokes,"tom_handwriting",2048,1048576);return strokes;}
QJsonArray lasso(const QJsonArray& strokes,const QJsonArray& polygon,bool wholeGroups){product::require(polygon.size()>=3&&polygon.size()<=128&&strokes.size()<=2048,"ink-lasso-capacity");for(auto p:polygon)point(p);auto selectionGroup=[](QJsonObject s){auto group=s["group"].toString();return group.isEmpty()?QString():group+(s.contains("component")?QString("/")+s["component"].toString():QString());};QSet<QString> ids,groups;std::uint64_t work=0;for(auto value:strokes){auto s=value.toObject();bool hitFill=false;if(s["shape"]=="polygon"){for(auto v:polygon){product::require((work+=s["points"].toArray().size())<=8000000,"ink-lasso-work-capacity");bool hit=inside(point(v),s["points"].toArray());for(auto hole:s["holes"].toArray()){product::require((work+=hole.toArray().size())<=8000000,"ink-lasso-work-capacity");hit=hit!=inside(point(v),hole.toArray());}hitFill|=hit;}if(hitFill){ids.insert(s["id"].toString());if(wholeGroups&&!s["group"].toString().isEmpty())groups.insert(selectionGroup(s));}}for(auto v:s["points"].toArray()){product::require((work+=polygon.size())<=8000000,"ink-lasso-work-capacity");if(inside(point(v),polygon)){ids.insert(s["id"].toString());if(wholeGroups&&!s["group"].toString().isEmpty())groups.insert(selectionGroup(s));break;}}}QJsonArray result;for(auto value:strokes){auto s=value.toObject();if(ids.contains(s["id"].toString())||groups.contains(selectionGroup(s)))result.append(s["id"]);}return result;}
Cut erase(const QJsonObject& stroke,const QJsonArray& eraser,double radius,std::uint64_t& work,std::uint64_t* broadphase){product::require(!eraser.isEmpty()&&eraser.size()<=2048&&std::isfinite(radius)&&radius>=1&&radius<=64,"ink-eraser-capacity");Cut out;const auto pts=stroke["points"].toArray();auto box=bounds({stroke}),eraseBox=bounds({QJsonObject{{"points",eraser}}});if(!box.adjusted(-radius-.001,-radius-.001,radius+.001,radius+.001).intersects(eraseBox)){out.pieces={pts};return out;}std::uint64_t local=0;auto& checks=broadphase?*broadphase:local;std::vector<QPointF> erased;erased.reserve(eraser.size());for(auto v:eraser)erased.push_back(point(v));auto hit=[&](QPointF p){for(std::size_t k=0;k<erased.size();++k){product::require(++checks<=16000000,"ink-eraser-broadphase-capacity");auto a=erased[k?k-1:0],b=erased[k];if(p.x()<std::min(a.x(),b.x())-radius||p.x()>std::max(a.x(),b.x())+radius||p.y()<std::min(a.y(),b.y())-radius||p.y()>std::max(a.y(),b.y())+radius)continue;product::require(++work<=8000000,"ink-eraser-work-capacity");if(distance(p,a,b)<=radius)return true;}return false;};
 if(stroke["shape"]=="polygon"){for(auto p:erased){product::require(++checks<=16000000,"ink-eraser-broadphase-capacity");if(!box.adjusted(-.001,-.001,.001,.001).contains(p))continue;product::require((work+=pts.size())<=8000000,"ink-eraser-work-capacity");bool in=inside(p,pts);for(auto hole:stroke["holes"].toArray()){product::require((work+=hole.toArray().size())<=8000000,"ink-eraser-work-capacity");in=in!=inside(p,hole.toArray());}if(in){out.hit=true;return out;}}QJsonArray rings{pts};for(auto h:stroke["holes"].toArray())rings.append(h);for(auto value:rings){auto ring=value.toArray();for(int i=0;i<ring.size();++i){auto b=point(ring[i]),a=point(ring[i?i-1:ring.size()-1]);int count=std::max(1,int(std::ceil(std::hypot((b-a).x(),(b-a).y())/std::max(.5,radius*.4))));product::require(count<=60000,"ink-eraser-sampling-capacity");for(int n=0;n<=count;++n)if(hit(a+(b-a)*(double(n)/count))){out.hit=true;return out;}}}out.pieces={pts};return out;} /* Filled regions erase as a whole; all outer and hole boundaries participate. */
 QJsonArray run;auto flush=[&]{if(run.size()>=2){product::require(out.pieces.size()<256,"ink-eraser-pieces-capacity");out.pieces.append(run);}run={};};for(int i=0;i<pts.size();++i){auto b=point(pts[i]),a=i?point(pts[i-1]):b;int count=std::max(1,int(std::ceil(std::hypot((b-a).x(),(b-a).y())/std::max(.5,radius*.4))));product::require(count<=60000,"ink-eraser-sampling-capacity");for(int n=i?1:0;n<=count;++n){double t=double(n)/count;auto p=a+(b-a)*t;if(hit(p)){out.hit=true;flush();}else{if(run.size()==2048){auto last=run.last();flush();run.append(last);}QJsonArray v{p.x(),p.y()};if(pts[i].toArray().size()==3)v.append(pts[i].toArray()[2]);run.append(v);}}}flush();if(!out.hit)out.pieces={pts};return out;}

void polygonSpans(const QJsonArray& polygon,int width,int height,const QJsonArray& matrix,const std::function<void(int,int,int)>& span,const QJsonArray& holes){product::require(polygon.size()>=3&&polygon.size()<=2048&&width>0&&width<=8192&&height>0&&height<=8192,"ink-fill-capacity");std::vector<std::vector<QPointF>> rings;QJsonArray all{polygon};for(auto h:holes)all.append(h);product::require(all.size()<=129,"ink-fill-holes-capacity");double top=height,bottom=0;unsigned total=0;for(auto source:all){std::vector<QPointF> ring;auto path=source.toArray();product::require(path.size()>=3&&path.size()<=2048,"ink-fill-path-capacity");ring.reserve(path.size());for(auto value:path){QPointF p;product::require(product::transformPoint(matrix,point(value),p),"ink-fill-transform");ring.push_back(p);top=std::min(top,p.y());bottom=std::max(bottom,p.y());++total;}rings.push_back(std::move(ring));}int y0=std::clamp(int(std::floor(top)),0,height),y1=std::clamp(int(std::ceil(bottom)),0,height);product::require(std::uint64_t(y1-y0)*total<=4000000,"ink-fill-work-capacity");std::vector<double> cuts;cuts.reserve(total);for(int y=y0;y<y1;++y){cuts.clear();double scan=y+.5;for(const auto& ring:rings)for(std::size_t i=0,j=ring.size()-1;i<ring.size();j=i++){auto a=ring[i],b=ring[j];if((a.y()>scan)!=(b.y()>scan))cuts.push_back(a.x()+(scan-a.y())*(b.x()-a.x())/(b.y()-a.y()));}std::sort(cuts.begin(),cuts.end());for(std::size_t i=1;i<cuts.size();i+=2){int x0=std::clamp(int(std::ceil(cuts[i-1]-.5)),0,width),x1=std::clamp(int(std::ceil(cuts[i]-.5)),0,width);if(x1>x0)span(y,x0,x1);}}}
QByteArray svg(const QJsonArray& strokes,double width,double height){product::require(std::isfinite(width)&&width>0&&width<=1480&&std::isfinite(height)&&height>0&&height<=17000&&strokes.size()<=2048,"ink-export-capacity");QString out=QString("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"%1\" height=\"%2\" viewBox=\"0 0 %1 %2\">\n").arg(width).arg(height);unsigned total=0;for(auto value:strokes){auto s=value.toObject(),style=s["style"].toObject();product::validateStyle(style);bool fill=s["shape"]=="polygon";QString path;QJsonArray all{s["points"].toArray()};for(auto hole:s["holes"].toArray())all.append(hole);for(auto ring:all){bool first=true;for(auto v:ring.toArray()){product::require(++total<=1048576,"ink-export-point-capacity");auto p=point(v);path+=QString(first?"M%1 %2 ":"L%1 %2 ").arg(p.x(),0,'f',3).arg(p.y(),0,'f',3);first=false;}if(fill)path+="Z ";}auto color=QString("#%1").arg(product::inkRgb(style),6,16,QChar('0')); /* exact color when the stroke has one */double pen=1.5;int wi=style["width"]=="thick"?2:style["width"]=="thin"?0:1;for(auto spec:product::toolSpecs())if(spec.toObject()["id"]==style["tool"])pen=spec.toObject()["widths"].toArray()[wi].toDouble();out+=QString("<path d=\"%1\" fill=\"%2\" fill-rule=\"evenodd\" stroke=\"%3\" stroke-width=\"%4\" stroke-linecap=\"round\" stroke-linejoin=\"round\" opacity=\"%5\"/>\n").arg(path,fill?color:"none",fill?"none":color).arg(pen).arg(s.value("opacity").toDouble(1));product::require(out.size()<=16*1024*1024,"ink-export-byte-capacity");}return (out+"</svg>\n").toUtf8();}
}
